{
  "architect_scope": "one-R44-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "The active family's separation of contract authority from terminal behavioral authority may create cross-boundary incoherence when downstream revision changes semantics without holistic authorship.",
    "causal_change": "Concentrate indivisible whole-policy semantic authorship in the first call and replace downstream behavioral revision with a zero-write custodial publication edge.",
    "expected_effect": "Joint authorship may preserve coherent tradeoffs across scan resistance and phase-shift adaptation by preventing downstream semantic drift.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "exclusive upstream whole-policy authorship with a zero-write terminal edge",
    "before": "The upstream call locks contract conformance while the terminal call retains authority to revise behavior-bearing semantics.",
    "after": "The upstream call holds indivisible authority over the complete policy artifact, while the terminal call has publication custody without semantic revision authority.",
    "why_structural": "This changes edge authority from downstream semantic transformation to upstream-exclusive authorship while retaining one sequential executable lineage."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "Contract conformance and behavior semantics require separate authorities.",
      "A terminal call must retain behavior-semantic revision authority.",
      "An executable handoff must transfer semantic authority."
    ],
    "forbidden_inherited_mechanism": "contract-locked executable relay with downstream behavior-semantic revision",
    "independent_replacement_principle": "A sole upstream author resolves contract and behavior jointly once, and the downstream edge provides semantic-preservation custody only.",
    "changed_behavioral_dimensions": [
      "scan-resistance behavior",
      "phase-shift adaptation behavior"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Sole-Writer Custodial Publication",
    "organization": "two-call sequential lineage with exclusive upstream semantic authority and a zero-write terminal edge",
    "information_flow": "The first call receives all common inputs and creates one complete executable policy capsule through holistic contract-and-behavior authorship. The terminal call consumes that capsule and public non-anchor evidence, receives no semantic modification authority, and emits the preserved policy.",
    "stages": [
      {
        "id": "sole_writer_custody_lineage",
        "mode": "sequential",
        "calls": [
          {
            "id": "author_indivisible_policy",
            "role": "sole whole-policy semantic authority",
            "objective": "Use the supplied evidence to form one complete executable policy capsule whose contract conformance and behavior-bearing semantics are jointly resolved, then pass the complete artifact forward without delegating semantic revision authority.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "policy_capsule"
          },
          {
            "id": "publish_without_revision",
            "role": "zero-write policy custodian",
            "objective": "Consume author_indivisible_policy and the supplied public evidence, preserve the complete executable artifact without semantic revision, and emit its single policy.",
            "inputs": [
              "author_indivisible_policy",
              "task",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "publish_without_revision"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
